import{_ as l,a0 as a,w as r,s as d,ao as u,I as s,x as n,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"從過時的 Windows 機器遷移到 Linux | LCTT x X-CMD","titleTemplate":false,"description":"從過時的 Windows 機器遷移到 Linux | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"從過時的 Windows 機器遷移到 Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"從過時的 Windows 機器遷移到 Linux | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180123 Moving to Linux from dated Windows machines","title":"從過時的 Windows 機器遷移到 Linux","tag":"201810","desc":""},"relativePath":"201810/20180123 Moving to Linux from dated Windows machines.md","filePath":"[post].md"}'),p={name:"201810/20180123 Moving to Linux from dated Windows machines.md"};function x(m,i,L,f,T,w){const t=a("Link");return r(),d("div",null,[i[16]||(i[16]=u('<h1 id="從過時的-windows-機器遷移到-linux" tabindex="-1">從過時的 Windows 機器遷移到 Linux <a class="header-anchor" href="#從過時的-windows-機器遷移到-linux" aria-label="Permalink to “從過時的 Windows 機器遷移到 Linux”">​</a></h1><blockquote><p>這是一個當老舊的 Windows 機器退役時，決定遷移到 Linux 的故事。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/1980s-computer-yearbook.png?itok=eGOYEKK-" alt=""></p><p>我在 ONLYOFFICE 的市場部門工作的每一天，我都能看到 Linux 用户在網上討論我們的辦公軟件。我們的產品在 Linux 用户中很受歡迎，這使得我對使用 Linux 作為日常工具的體驗非常好奇。我的老舊的 Windows XP 機器在性能上非常差，因此我決定了解 Linux 系統（特別是 Ubuntu）並且決定去嘗試使用它。我的兩個同事也加入了我的計劃。</p><h3 id="為何選擇-linux" tabindex="-1">為何選擇 Linux ？ <a class="header-anchor" href="#為何選擇-linux" aria-label="Permalink to “為何選擇 Linux ？”">​</a></h3><p>我們必須做出改變，首先，我們的老系統在性能方面不夠用：我們經歷過頻繁的崩潰，每當運行超過兩個應用時，機器就會負載過度，關閉機器時有一半的幾率凍結等等。這很容易讓我們從工作中分心，意味着我們沒有我們應有的工作效率了。</p><p>升級到 Windows 的新版本也是一種選擇，但這樣可能會帶來額外的開銷，而且我們的軟件本身也是要與 Microsoft 的辦公軟件競爭。因此我們在這方面也存在意識形態的問題。</p><p>其次，就像我之前提過的， ONLYOFFICE 產品在 Linux 社區內非常受歡迎。通過閲讀 Linux 用户在使用我們的軟件時的體驗，我們也對加入他們很感興趣。</p>',8)),s("p",null,[i[1]||(i[1]=n("在我們要求轉換到 Linux 系統一週後，我們拿到了嶄新的裝好了 ",-1)),o(t,{href:"https://kubuntu.org/"},{default:e(()=>[...i[0]||(i[0]=[n("Kubuntu",-1)])]),_:1}),i[2]||(i[2]=n(" 的機器。我們選擇了 16.04 版本，因為這個版本支持 KDE Plasma 5.5 和包括 Dolphin 在內的很多 KDE 應用，同時也包括 LibreOffice 5.1 和 Firefox 45 。",-1))]),i[17]||(i[17]=u('<h3 id="linux-讓人喜歡的地方" tabindex="-1">Linux 讓人喜歡的地方 <a class="header-anchor" href="#linux-讓人喜歡的地方" aria-label="Permalink to “Linux 讓人喜歡的地方”">​</a></h3><p>我相信 Linux 最大的優勢是它的運行速度，比如，從按下機器的電源按鈕到開始工作只需要幾秒鐘時間。從一開始，一切看起來都超乎尋常地快：總體的響應速度，圖形界面，甚至包括系統更新的速度。</p><p>另一個使我驚奇的事情是跟 Windows 相比， Linux 幾乎能讓你配置任何東西，包括整個桌面的外觀。在設置裏面，我發現瞭如何修改各種欄目、按鈕和字體的顏色和形狀，也可以重新佈置任意桌面組件的位置，組合桌面小工具（甚至包括漫畫和顏色選擇器）。我相信我還僅僅只是瞭解了基本的選項，之後還需要探索這個系統更多著名的定製化選項。</p><p>Linux 發行版通常是一個非常安全的環境。人們很少在 Linux 系統中使用防病毒的軟件，因為很少有人會寫病毒程序來攻擊 Linux 系統。因此你可以擁有很好的系統速度，並且節省了時間和金錢。</p><p>總之， Linux 已經改變了我們的日常生活，用一系列的新選項和功能大大震驚了我們。僅僅通過短時間的使用，我們已經可以給它總結出以下特性：</p><ul><li>操作很快很順暢</li><li>高度可定製</li><li>對新手很友好</li><li>瞭解基本組件很有挑戰性，但回報豐厚</li><li>安全可靠</li><li>對所有想改變工作場所的人來説都是一次絕佳的體驗</li></ul><p>你已經從 Windows 或 MacOS 系統換到 Kubuntu 或其他 Linux 變種了麼？或者你是否正在考慮做出改變？請分享你想要採用 Linux 系統的原因，連同你對開源的印象一起寫在評論中。</p><hr>',8)),s("p",null,[i[4]||(i[4]=n("via: ",-1)),o(t,{href:"https://opensource.com/article/18/1/move-to-linux-old-windows"},{default:e(()=>[...i[3]||(i[3]=[n("https://opensource.com/article/18/1/move-to-linux-old-windows",-1)])]),_:1})]),s("p",null,[i[8]||(i[8]=n("作者：",-1)),o(t,{href:"https://opensource.com/users/michaelk"},{default:e(()=>[...i[5]||(i[5]=[n("Michael Korotaev",-1)])]),_:1}),i[9]||(i[9]=n(" 譯者：",-1)),o(t,{href:"https://github.com/bookug"},{default:e(()=>[...i[6]||(i[6]=[n("bookug",-1)])]),_:1}),i[10]||(i[10]=n(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:e(()=>[...i[7]||(i[7]=[n("wxy",-1)])]),_:1})]),s("p",null,[i[13]||(i[13]=n("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[11]||(i[11]=[n("LCTT",-1)])]),_:1}),i[14]||(i[14]=n(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:e(()=>[...i[12]||(i[12]=[n("Linux中國",-1)])]),_:1}),i[15]||(i[15]=n(" 榮譽推出",-1))])])}const W=l(p,[["render",x]]);export{g as __pageData,W as default};
